import random
from eywa.state import MachineRuntime
from eywa.expr import ExprCompiler
from eywa.model import TypeSystem
comp=ExprCompiler(TypeSystem([]))
def brute(states,initial,trans,target):
 best=None
 adj={s:[] for s in states}
 for i,t in enumerate(trans): adj[t['from']].append((t['to'],t['cost'],t['command'],i))
 def dfs(u,seen,cost,hops,seq):
  nonlocal best
  if u==target:
   key=(cost,hops,tuple(seq))
   if best is None or key<best[0]: best=(key,cost,list(seq))
   return
  for v,c,cmd,i in adj[u]:
   if v in seen: continue
   seen.add(v);seq.append(cmd)
   dfs(v,seen,cost+c,hops+1,seq)
   seq.pop();seen.remove(v)
 dfs(initial,{initial},0,0,[])
 return None if best is None else (best[2],best[1])
def fromrt(states,initial,trans,target):
 m={'states':states,'initial':initial,'state_param':'s','message_param':'m','transitions':trans}
 rt=MachineRuntime(m,comp)
 return rt.prepare(target,{})
random.seed(1)
for trial in range(10000):
 n=random.randint(1,8)
 states=[f'S{i}' for i in range(n)]
 initial=states[0]
 transitions=[];pairs=set()
 for i in range(random.randint(0,18)):
  fr=random.randrange(n);to=random.randrange(n);cmd=random.choice(['a','b','c','aa','z','ab'])
  if (fr,cmd) in pairs: continue
  pairs.add((fr,cmd));transitions.append({'from':states[fr],'to':states[to],'command':cmd,'cost':random.randint(1,8),'when':None})
 target=random.choice(states)
 b=brute(states,initial,transitions,target); r=fromrt(states,initial,transitions,target)
 if (b is None)!=(r is None) or (b is not None and (b[0]!=r[0] or b[1]!=r[1])):
  print('MISMATCH',trial,states,initial,transitions,target,'brute',b,'rt',r);break
else: print('all ok')
